// Some portions generated by Claude
/**
 * The Filters panel's values from the repository: for every drawn resource, all of its outgoing predicates and their
 * values, whether or not those statements are loaded into the graph (.agent/workbench-repository-facets-execplan.md).
 *
 * Most nodes come in one request per batch, at most STATEMENTS_PER_NODE statements each; a node that reaches that cap
 * is large and is counted per predicate (a census), probed for predicates the census may not have reached, and asked
 * for its values one predicate at a time, at most VALUES_PER_CELL per predicate. Batches are sized to stay below the
 * servlet's row limit, which cuts results off without saying so. Two requests run at a time, and none starts while the
 * explorer's own queries run. Entries live in memory for the session and, through `persistence`, in IndexedDB.
 */
import { BLANK_VALUE_ID, LONG_LITERAL_LENGTH, LONG_LITERAL_VALUE_ID } from "./facet-value-ids.ts";
import { isQueryableResource, isSparqlTerm, sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";
import {
  predicateCensusQuery,
  predicateProbeQuery,
  predicateValuesQuery,
  statementsQuery,
  type GraphScope,
} from "./rdf-vocabulary.ts";
import { QueryFailure } from "./request-batching.ts";

/** A node with fewer statements than this is complete after one request. */
export const STATEMENTS_PER_NODE = 101;
/** Values kept per (node, predicate); a cell with more is incomplete. */
export const VALUES_PER_CELL = 1000;
/** Statements a census reads per large node before it stops counting. */
export const CENSUS_CAP = 10_001;
/** A literal longer than this only records that the node has the predicate (facet-value-ids.ts). */
export { LONG_LITERAL_LENGTH };
export { LONG_LITERAL_VALUE_ID };

const DEFAULT_MAX_ROWS = 5000;
const DEFAULT_MAX_QUERY_LENGTH = 150_000;
const DEFAULT_BUDGET = 100_000;
const DEFAULT_TIMEOUT_MS = 30_000;
/** Characters a query may use, leaving room for what the servlet adds. */
const QUERY_LENGTH_MARGIN = 2_000;
const TRANSIENT = new Set([408, 413, 414, 429, 502, 503, 504]);
const PRIORITY = { focus: 0, viewport: 1, background: 2 } as const;
const RETRIES = 2;
const PROBE_CANDIDATES = 200;

export type Priority = keyof typeof PRIORITY;
export type RepositoryCell = { values: string[]; complete: boolean };
export type RepositoryEntry = {
  predicates: Map<string, RepositoryCell>;
  /** False when a census stopped at its cap: predicates no probe asked for may be missing. */
  predicatesComplete: boolean;
  checkedAt: number;
};
/** An entry as stored: plain JSON. */
export type StoredEntry = {
  checkedAt: number;
  predicatesComplete: boolean;
  predicates: Array<[string, string[], boolean]>;
};
export type FacetStorePersistence = {
  /** The stored entries of these nodes that are still fresh. */
  read(ids: string[]): Promise<Map<string, StoredEntry>>;
  write(entries: Map<string, StoredEntry>): Promise<void>;
  clear(): Promise<void>;
};
type Binding = Record<string, SparqlTerm | undefined>;
export type FacetQuery = (query: string, signal: AbortSignal) => Promise<{ results?: { bindings?: Binding[] } }>;

export type RepositoryFacetStoreOptions = {
  execute: FacetQuery;
  scope: GraphScope;
  /** The servlet's row limit (graph-max-result-rows). */
  maxRows?: number;
  /** The servlet's query length limit (graph-max-query-length). */
  maxQueryLength?: number;
  concurrency?: number;
  timeoutMs?: number;
  /** Value rows loaded for background nodes before the store waits for a nearer reason to load more. */
  budget?: number;
  perNodeCap?: number;
  censusCap?: number;
  now?: () => number;
  persistence?: FacetStorePersistence;
  /** Resolves when the explorer's own queries are done; background requests wait for it. */
  foreground?: { idle(): Promise<void> };
  /** Predicates to probe a capped hub for, besides those other nodes have (for example the loaded edges'). */
  candidates?: () => Iterable<string>;
};

export type RepositoryFacetStatus = {
  wanted: number;
  loaded: number;
  loading: number;
  failed: number;
  budgetExhausted: boolean;
};

type Job = { kind: "statements"; ids: string[] } | { kind: "large"; id: string };

/** The value id a repository term is listed under: blank nodes the store cannot name and long texts are summarised. */
export function repositoryValueId(term: SparqlTerm | undefined): string | null {
  if (!isSparqlTerm(term)) return null;
  if (term.type === "bnode") return term["rdf4j:reference"] === true ? sparqlNodeId(term) : BLANK_VALUE_ID;
  if (term.type !== "uri" && term.value.length > LONG_LITERAL_LENGTH) return LONG_LITERAL_VALUE_ID;
  return sparqlNodeId(term);
}

export function toStoredEntry(entry: RepositoryEntry): StoredEntry {
  return {
    checkedAt: entry.checkedAt,
    predicatesComplete: entry.predicatesComplete,
    predicates: [...entry.predicates].map(([predicate, cell]) => [predicate, cell.values, cell.complete]),
  };
}

export function fromStoredEntry(stored: StoredEntry): RepositoryEntry {
  return {
    checkedAt: stored.checkedAt,
    predicatesComplete: stored.predicatesComplete,
    predicates: new Map(stored.predicates.map(([predicate, values, complete]) => [predicate, { values, complete }])),
  };
}

const abortError = () => new DOMException("Request cancelled", "AbortError");
const isAbort = (error: unknown) => error instanceof DOMException && error.name === "AbortError";
const wait = (milliseconds: number) => new Promise((resolve) => setTimeout(resolve, milliseconds));

export class RepositoryFacetStore {
  version = 0;
  private readonly execute: FacetQuery;
  private readonly scope: GraphScope;
  private readonly maxRows: number;
  private readonly maxQueryLength: number;
  private readonly concurrency: number;
  private readonly timeoutMs: number;
  private readonly budget: number;
  private readonly perNodeCap: number;
  private readonly censusCap: number;
  private readonly now: () => number;
  private readonly persistence?: FacetStorePersistence;
  private readonly foreground?: { idle(): Promise<void> };
  private readonly candidates?: () => Iterable<string>;
  private readonly maxBatch: number;
  private batchSize: number;

  private entries = new Map<string, RepositoryEntry>();
  /** The predicates of the entries, and as a list (predicates()) until a new one arrives. */
  private predicateSet = new Set<string>();
  private predicateList: readonly string[] | null = null;
  private wanted = new Map<string, number>();
  /** Nodes waiting for a statements request, by priority. */
  private queued = new Map<string, number>();
  /** Large nodes waiting for a census, by priority. */
  private large = new Map<string, number>();
  private inFlight = new Set<string>();
  private lookups = new Set<string>();
  private failed = new Set<string>();
  private retries = new Map<string, number>();
  private active = 0;
  private generation = 0;
  private budgetUsed = 0;
  private pumpScheduled = false;
  private disposed = false;
  private controller = new AbortController();
  private listeners = new Set<() => void>();

  constructor(options: RepositoryFacetStoreOptions) {
    this.execute = options.execute;
    this.scope = options.scope;
    this.maxRows = Math.max(2, options.maxRows ?? DEFAULT_MAX_ROWS);
    this.maxQueryLength = Math.max(4_000, options.maxQueryLength ?? DEFAULT_MAX_QUERY_LENGTH) - QUERY_LENGTH_MARGIN;
    this.concurrency = Math.max(1, options.concurrency ?? 2);
    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.budget = options.budget ?? DEFAULT_BUDGET;
    this.perNodeCap = options.perNodeCap ?? STATEMENTS_PER_NODE;
    this.censusCap = options.censusCap ?? CENSUS_CAP;
    this.now = options.now ?? Date.now;
    this.persistence = options.persistence;
    this.foreground = options.foreground;
    this.candidates = options.candidates;
    // Below the row limit even when every node of a batch reaches its cap: a full reply cannot be a cut-off one.
    this.maxBatch = Math.max(1, Math.floor((this.maxRows - 1) / this.perNodeCap));
    this.batchSize = this.maxBatch;
  }

  /** Asks for these nodes' values; nodes already known, loading or queued are left alone (a nearer priority wins). */
  want(nodeIds: readonly string[], priority: Priority) {
    if (this.disposed) return;
    const rank = PRIORITY[priority];
    const fresh: string[] = [];
    for (const id of nodeIds) {
      if (!isQueryableResource(id)) continue;
      this.wanted.set(id, Math.min(rank, this.wanted.get(id) ?? rank));
      if (this.entries.has(id) || this.inFlight.has(id) || this.lookups.has(id)) continue;
      const queued = this.queued.get(id) ?? this.large.get(id);
      if (queued !== undefined) {
        if (rank < queued) (this.queued.has(id) ? this.queued : this.large).set(id, rank);
        continue;
      }
      // A node that failed is asked for again only when it comes into focus.
      if (this.failed.has(id) && rank > PRIORITY.focus) continue;
      this.failed.delete(id);
      fresh.push(id);
    }
    if (!fresh.length) return this.schedulePump();
    if (!this.persistence) {
      fresh.forEach((id) => this.queued.set(id, rank));
      return this.schedulePump();
    }
    const generation = this.generation;
    fresh.forEach((id) => this.lookups.add(id));
    this.persistence
      .read(fresh)
      .catch(() => new Map<string, StoredEntry>())
      .then((stored) => {
        fresh.forEach((id) => this.lookups.delete(id));
        if (this.disposed) return;
        if (generation !== this.generation) {
          this.want(fresh, priority);
          return;
        }
        let found = 0;
        for (const id of fresh) {
          const entry = stored.get(id);
          if (entry) {
            this.setEntry(id, fromStoredEntry(entry));
            found++;
          } else this.queued.set(id, Math.min(rank, this.wanted.get(id) ?? rank));
        }
        if (found) this.notify();
        this.schedulePump();
      });
  }

  get(nodeId: string): RepositoryEntry | undefined {
    return this.entries.get(nodeId);
  }

  /** Every predicate of the loaded nodes: the explorer learns label predicates from them (RdfExplorer.learnPredicates). */
  predicates(): readonly string[] {
    return (this.predicateList ??= [...this.predicateSet]);
  }

  private setEntry(id: string, entry: RepositoryEntry) {
    this.entries.set(id, entry);
    entry.predicates.forEach((_, predicate) => {
      if (this.predicateSet.has(predicate)) return;
      this.predicateSet.add(predicate);
      this.predicateList = null;
    });
  }

  status(): RepositoryFacetStatus {
    const exhausted = this.budgetUsed >= this.budget;
    const runnable = (ranks: Map<string, number>) =>
      exhausted ? [...ranks.values()].filter((rank) => rank < PRIORITY.background).length : ranks.size;
    let loaded = 0;
    this.wanted.forEach((_, id) => {
      if (this.entries.has(id)) loaded++;
    });
    const waiting = [...this.queued.values(), ...this.large.values()].some((rank) => rank === PRIORITY.background);
    return {
      wanted: this.wanted.size,
      loaded,
      loading: this.inFlight.size + this.lookups.size + runnable(this.queued) + runnable(this.large),
      failed: this.failed.size,
      budgetExhausted: exhausted && waiting,
    };
  }

  subscribe(listener: () => void) {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /** Forgets every value (memory and storage) and asks again for the nodes that are wanted. */
  clear() {
    this.generation++;
    this.entries.clear();
    this.predicateSet.clear();
    this.predicateList = null;
    this.failed.clear();
    this.retries.clear();
    this.budgetUsed = 0;
    this.queued.clear();
    this.large.clear();
    void this.persistence?.clear().catch(() => undefined);
    const wanted = [...this.wanted];
    this.wanted.clear();
    this.notify();
    for (const [rank, ids] of groupByRank(wanted)) this.want(ids, rankName(rank));
  }

  dispose() {
    this.disposed = true;
    this.controller.abort();
    this.listeners.clear();
    this.queued.clear();
    this.large.clear();
  }

  private notify() {
    this.version++;
    this.listeners.forEach((listener) => listener());
  }

  private schedulePump() {
    // Wants made in the same turn are ordered together: a focused node asked for right after a batch goes first.
    if (this.pumpScheduled) return;
    this.pumpScheduled = true;
    queueMicrotask(() => {
      this.pumpScheduled = false;
      this.pump();
    });
  }

  private pump() {
    while (!this.disposed && this.active < this.concurrency) {
      const job = this.nextJob();
      if (!job) break;
      this.active++;
      void this.run(job).finally(() => {
        this.active--;
        // The status changed (a batch was split, retried or finished): the panel's progress follows.
        this.notify();
        this.pump();
      });
    }
  }

  private nextJob(): Job | null {
    const exhausted = this.budgetUsed >= this.budget;
    const allowed = (rank: number) => !exhausted || rank < PRIORITY.background;
    const best = (ranks: Map<string, number>) => {
      let found: [string, number] | null = null;
      for (const entry of ranks) if (allowed(entry[1]) && (!found || entry[1] < found[1])) found = entry;
      return found;
    };
    const statement = best(this.queued);
    const large = best(this.large);
    if (large && (!statement || large[1] < statement[1])) {
      this.large.delete(large[0]);
      return { kind: "large", id: large[0] };
    }
    if (!statement) return null;
    const rank = statement[1];
    const ids: string[] = [];
    let length = 64;
    for (const [id, idRank] of this.queued) {
      if (idRank !== rank) continue;
      const cost = 160 + id.length * (this.scope === "all" ? 2 : 1);
      if (ids.length && (ids.length >= this.batchSize || length + cost > this.maxQueryLength)) break;
      ids.push(id);
      length += cost;
    }
    ids.forEach((id) => this.queued.delete(id));
    return { kind: "statements", ids };
  }

  private async request(query: string): Promise<Binding[]> {
    await this.foreground?.idle();
    if (this.disposed) throw abortError();
    const timeout = AbortSignal.timeout(this.timeoutMs);
    const signal = AbortSignal.any([this.controller.signal, timeout]);
    try {
      return (await this.execute(query, signal)).results?.bindings ?? [];
    } catch (error) {
      if (timeout.aborted && !this.controller.signal.aborted) throw new QueryFailure("The repository took too long.", 408);
      throw error;
    }
  }

  private async run(job: Job) {
    const generation = this.generation;
    const ids = job.kind === "statements" ? job.ids : [job.id];
    const ranks = new Map(ids.map((id) => [id, this.wanted.get(id) ?? PRIORITY.background]));
    ids.forEach((id) => this.inFlight.add(id));
    const requeue = (target: Map<string, number>, which = ids) =>
      which.forEach((id) => {
        if (this.wanted.has(id)) target.set(id, ranks.get(id)!);
      });
    try {
      const started = this.now();
      const result =
        job.kind === "statements" ? await this.loadStatements(job.ids) : await this.loadLarge(job.id);
      if (this.disposed) return;
      if (generation !== this.generation) {
        // A refresh came while this was loading: the answer may be from before it.
        ids.forEach((id) => this.inFlight.delete(id));
        requeue(job.kind === "statements" ? this.queued : this.large);
        return;
      }
      if (result.saturated) {
        ids.forEach((id) => this.inFlight.delete(id));
        if (job.kind === "statements" && ids.length > 1) {
          this.batchSize = Math.max(1, Math.floor(ids.length / 2));
          requeue(this.queued);
        } else requeue(this.large);
        return;
      }
      const stored = new Map<string, StoredEntry>();
      result.entries.forEach((entry, id) => {
        this.setEntry(id, entry);
        this.retries.delete(id);
        stored.set(id, toStoredEntry(entry));
        entry.predicates.forEach((cell) => (this.budgetUsed += cell.values.length));
      });
      ids.forEach((id) => this.inFlight.delete(id));
      requeue(this.large, result.large);
      if (job.kind === "statements" && this.now() - started < 600 && this.batchSize < this.maxBatch)
        this.batchSize = Math.min(this.maxBatch, this.batchSize + 4);
      if (stored.size) void this.persistence?.write(stored).catch(() => undefined);
      if (result.entries.size) this.notify();
    } catch (error) {
      ids.forEach((id) => this.inFlight.delete(id));
      if (this.disposed || (isAbort(error) && this.controller.signal.aborted)) return;
      if (generation !== this.generation) {
        requeue(job.kind === "statements" ? this.queued : this.large);
        return;
      }
      const status = error instanceof QueryFailure ? error.status : 0;
      if (job.kind === "statements" && ids.length > 1) {
        // A batch that failed is asked for again in halves: one node may be the cause, or the batch too large.
        this.batchSize = Math.max(1, Math.floor(ids.length / 2));
        if (status === 429 || status === 503) await wait(Math.min(30_000, Math.max(200, (error as QueryFailure).retryAfterMs)));
        requeue(this.queued);
      } else {
        const id = ids[0];
        const tries = (this.retries.get(id) ?? 0) + 1;
        if (TRANSIENT.has(status) && tries <= RETRIES) {
          this.retries.set(id, tries);
          await wait(200 * tries);
          requeue(job.kind === "statements" ? this.queued : this.large);
        } else {
          this.retries.delete(id);
          this.failed.add(id);
          this.notify();
        }
      }
    }
  }

  private async loadStatements(ids: string[]) {
    const rows = await this.request(statementsQuery(ids, this.scope, this.perNodeCap));
    const entries = new Map<string, RepositoryEntry>();
    const large: string[] = [];
    if (rows.length >= this.maxRows) return { saturated: true, entries, large };
    const bySubject = new Map<string, Binding[]>();
    for (const row of rows) {
      if (!isSparqlTerm(row.s)) continue;
      const subject = sparqlNodeId(row.s);
      const list = bySubject.get(subject);
      if (list) list.push(row);
      else bySubject.set(subject, [row]);
    }
    const checkedAt = this.now();
    for (const id of ids) {
      const statements = bySubject.get(id) ?? [];
      if (statements.length >= this.perNodeCap) {
        large.push(id);
        continue;
      }
      const predicates = new Map<string, RepositoryCell>();
      for (const row of statements) addValue(predicates, row.p, row.o);
      entries.set(id, { predicates, predicatesComplete: true, checkedAt });
    }
    return { saturated: false, entries, large };
  }

  /** A large node: census, probes when the census stopped at its cap, then values per predicate. */
  private async loadLarge(id: string) {
    const census = new Map<string, number>();
    for (const row of await this.request(predicateCensusQuery(id, this.scope, this.censusCap))) {
      if (row.p?.type !== "uri") continue;
      census.set(row.p.value, Number(row.n?.value) || 0);
    }
    const counted = [...census.values()].reduce((sum, count) => sum + count, 0);
    const capped = counted >= this.censusCap;
    if (capped) {
      for (const chunk of this.chunks(this.probeCandidates(census), () => 160 + id.length)) {
        for (const row of await this.request(predicateProbeQuery(id, chunk, this.scope))) {
          if (row.p?.type === "uri" && !census.has(row.p.value)) census.set(row.p.value, VALUES_PER_CELL + 1);
        }
      }
    }
    const predicates = new Map<string, RepositoryCell>();
    let chunk: string[] = [];
    let rows = 0;
    let length = 64;
    const flush = async () => {
      if (!chunk.length) return;
      const asked = chunk;
      chunk = [];
      rows = 0;
      length = 64;
      const found = await this.request(predicateValuesQuery(id, asked, this.scope, VALUES_PER_CELL + 1));
      for (const row of found) {
        addValue(predicates, row.p, row.o);
      }
      // A capped census undercounts, so a reply can reach the servlet's row cap and lose values: none is complete.
      const cut = found.length >= this.maxRows;
      for (const predicate of asked) {
        const cell = predicates.get(predicate);
        if (!cell) continue;
        const expected = census.get(predicate) ?? 0;
        if (cell.values.length > VALUES_PER_CELL) cell.values.length = VALUES_PER_CELL;
        cell.complete = !cut && cell.values.length < VALUES_PER_CELL && (capped || cell.values.length >= Math.min(expected, VALUES_PER_CELL));
        if (cell.values.length >= VALUES_PER_CELL && expected > VALUES_PER_CELL) cell.complete = false;
      }
    };
    for (const [predicate, count] of [...census].sort((left, right) => left[1] - right[1])) {
      const cost = Math.min(count, VALUES_PER_CELL + 1);
      const size = 200 + predicate.length * 2 + id.length * (this.scope === "all" ? 2 : 1);
      if (chunk.length && (rows + cost >= this.maxRows || length + size > this.maxQueryLength)) await flush();
      chunk.push(predicate);
      rows += cost;
      length += size;
    }
    await flush();
    const entries = new Map([[id, { predicates, predicatesComplete: !capped, checkedAt: this.now() } as RepositoryEntry]]);
    return { saturated: false, entries, large: [] as string[] };
  }

  /** Predicates other nodes have, most common first, and the caller's candidates: what a capped census may miss. */
  private probeCandidates(known: ReadonlyMap<string, number>) {
    const counts = new Map<string, number>();
    this.entries.forEach((entry) => entry.predicates.forEach((_, predicate) => counts.set(predicate, (counts.get(predicate) ?? 0) + 1)));
    for (const predicate of this.candidates?.() ?? []) counts.set(predicate, (counts.get(predicate) ?? 0) + 1);
    return [...counts]
      .filter(([predicate]) => !known.has(predicate) && /^[A-Za-z][A-Za-z0-9+.-]*:[^<>"{}|^`\\\s]*$/.test(predicate))
      .sort((left, right) => right[1] - left[1])
      .slice(0, PROBE_CANDIDATES)
      .map(([predicate]) => predicate);
  }

  private chunks(values: string[], cost: (value: string) => number) {
    const result: string[][] = [];
    let current: string[] = [];
    let length = 64;
    for (const value of values) {
      const size = cost(value) + value.length;
      if (current.length && length + size > this.maxQueryLength) {
        result.push(current);
        current = [];
        length = 64;
      }
      current.push(value);
      length += size;
    }
    if (current.length) result.push(current);
    return result;
  }
}

function addValue(predicates: Map<string, RepositoryCell>, predicateTerm: SparqlTerm | undefined, object: SparqlTerm | undefined) {
  if (predicateTerm?.type !== "uri") return;
  const value = repositoryValueId(object);
  if (value === null) return;
  let cell = predicates.get(predicateTerm.value);
  if (!cell) predicates.set(predicateTerm.value, (cell = { values: [], complete: true }));
  if (!cell.values.includes(value)) cell.values.push(value);
}

function groupByRank(wanted: Array<[string, number]>) {
  const groups = new Map<number, string[]>();
  for (const [id, rank] of wanted) {
    const list = groups.get(rank);
    if (list) list.push(id);
    else groups.set(rank, [id]);
  }
  return groups;
}

function rankName(rank: number): Priority {
  return rank === PRIORITY.focus ? "focus" : rank === PRIORITY.viewport ? "viewport" : "background";
}
